package com.quicknotes.app;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;import java.util.*;
public class Reminders extends BroadcastReceiver {
 static final String PREFS="alarm-state";
 static PendingIntent alarm(Context c,String id,long expected){return PendingIntent.getBroadcast(c,0,new Intent(c,Reminders.class).setAction("reminder:"+id).putExtra("id",id).putExtra("expectedDue",expected),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static JSONObject read(Context c)throws Exception{try(InputStream in=new FileInputStream(new File(c.getFilesDir(),"data.json"))){return MainActivity.validate(new JSONObject(new String(MainActivity.bytes(in,MainActivity.MAX_BUNDLE),"UTF-8")));}}
 static void write(Context c,JSONObject d)throws Exception{File temp=new File(c.getFilesDir(),"alarm-data.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(d.toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(new File(c.getFilesDir(),"data.json")))throw new IOException("Cannot save reminder state");ReminderWidget.refresh(c);}
 static boolean exactAllowed(Context c){return Build.VERSION.SDK_INT<31||((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();}
 static boolean activeList(JSONObject d,String id)throws Exception{JSONArray lists=d.getJSONArray("lists");for(int n=0;n<lists.length();n++){JSONObject l=lists.getJSONObject(n);if(id.equals(l.optString("id"))&&!l.optBoolean("deleted"))return true;}return false;}
 static long earlyTime(JSONObject i){long due=i.optLong("due");if(i.optString("earlyUnit").equals("months")){Calendar cal=Calendar.getInstance();cal.setTimeInMillis(due);cal.add(Calendar.MONTH,-Math.max(1,Math.min(999,i.optInt("earlyAmount",1))));return cal.getTimeInMillis();}return due-Math.max(0,Math.min(10069920L,i.optLong("earlyMinutes")))*60000L;}
 static boolean hasEarly(JSONObject i){return i.optLong("earlyMinutes")>0||i.optString("earlyUnit").equals("months");}
 // Urgent reminders never publish pre-due notifications, including early reminders.
 static boolean waitingForUrgentDue(JSONObject item,long now){return item.optBoolean("urgent")&&(item.optLong("due")<=0||item.optLong("due")>now);}
 // Flagged reminders need a real due date; early alerts never create a timer.
 static boolean waitingForNotificationDue(JSONObject item,long now){return waitingForUrgentDue(item,now)||(item.optBoolean("flag")&&(item.optLong("due")<=0||item.optLong("due")>now));}
 static void reconcileNotifications(Context c,JSONObject d)throws Exception{NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);for(android.service.notification.StatusBarNotification notice:nm.getActiveNotifications()){String id=notice.getTag();if(id==null)continue;JSONObject i=find(d,id);Notification n=notice.getNotification();if(i==null||waitingForNotificationDue(i,System.currentTimeMillis())||i.optBoolean("done")||i.optBoolean("deleted")||!activeList(d,i.optString("list"))||(n.extras.getBoolean("quicknotes.live")&&!i.optBoolean("flag"))||i.optLong("due")!=n.extras.getLong("quicknotes.due",i.optLong("due")))nm.cancel(id,notice.getId());else if(!n.extras.getBoolean("quicknotes.early")&&i.optBoolean("flag")!=((n.flags&Notification.FLAG_ONGOING_EVENT)!=0))notifyReminder(c,i,false,false);}}
 static long scheduledDue(JSONObject i){return !i.optBoolean("done")?i.optLong("due"):0;}
 static JSONObject find(JSONObject d,String id)throws Exception{JSONArray a=d.getJSONArray("items");for(int n=0;n<a.length();n++)if(id.equals(a.getJSONObject(n).getString("id")))return a.getJSONObject(n);return null;}
 static boolean reactivate(JSONObject d,long now)throws Exception{return Repeats.migrate(d,now);}
 static PendingIntent early(Context c,String id,long due){return PendingIntent.getBroadcast(c,0,new Intent(c,Reminders.class).setAction("early:"+id).putExtra("id",id).putExtra("expectedDue",due).putExtra("early",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,JSONObject d)throws Exception{
  AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray items=d.getJSONArray("items");SharedPreferences prefs=c.getSharedPreferences(PREFS,0);long now=System.currentTimeMillis();
  for(int n=0;n<items.length();n++){JSONObject i=items.getJSONObject(n);String id=i.getString("id");long due=scheduledDue(i);PendingIntent pi=alarm(c,id,due);am.cancel(pi);PendingIntent ep=early(c,id,due);am.cancel(ep);
   boolean active=!i.optBoolean("deleted")&&activeList(d,i.optString("list"));long snooze=prefs.getLong("snooze:"+id,0);long snoozeDue=prefs.getLong("snooze-due:"+id,0);if(snooze>now&&snoozeDue==due&&active&&!i.optBoolean("done"))due=snooze;else if(snooze>0)prefs.edit().remove("snooze:"+id).remove("snooze-due:"+id).apply();
   long earlyTime=earlyTime(i);if(active&&!i.optBoolean("done")&&!i.optBoolean("urgent")&&!i.optBoolean("flag")&&hasEarly(i)&&earlyTime>now){if(exactAllowed(c))am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,earlyTime,ep);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,earlyTime,ep);}
   if(active&&due>now){if(i.optBoolean("urgent")&&i.optBoolean("timeEnabled",true)){if(exactAllowed(c)&&((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled()){PendingIntent show=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.setAlarmClock(new AlarmManager.AlarmClockInfo(due,show),pi);}else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}else if(exactAllowed(c))am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,due,pi);}
  }
  for(int n=0;n<items.length();n++){JSONObject i=items.getJSONObject(n);String id=i.getString("id");long due=i.optLong("due");if(i.optBoolean("deleted")||i.optBoolean("done")||!activeList(d,i.optString("list")))continue;
   if(due>0&&due<=now&&prefs.getLong("snooze:"+id,0)<=now&&prefs.getLong("delivered:"+id,-1)!=due)notifyReminder(c,i);
   else if(i.optBoolean("flag")&&!i.optBoolean("urgent")&&!waitingForNotificationDue(i,now)&&prefs.getLong("delivered:"+id,-1)==due)notifyReminder(c,i,false,false);
  }
  reconcileNotifications(c,d);AlarmService.reconcile(c,d);
 }
 @Override public void onReceive(Context c,Intent intent){PendingResult pending=goAsync();new Thread(()->{try{synchronized(MainActivity.STORE_LOCK){JSONObject d=read(c);String action=intent.getAction();if(Intent.ACTION_BOOT_COMPLETED.equals(action)||Intent.ACTION_MY_PACKAGE_REPLACED.equals(action)||Intent.ACTION_TIME_CHANGED.equals(action)||Intent.ACTION_TIMEZONE_CHANGED.equals(action)||AlarmManager.ACTION_SCHEDULE_EXACT_ALARM_PERMISSION_STATE_CHANGED.equals(action)){if(reactivate(d,System.currentTimeMillis()))write(c,d);schedule(c,d);return;}
  String id=intent.getStringExtra("id");if("WIDGET_ROW".equals(action)&&!intent.getBooleanExtra("widgetComplete",false)){Intent open=new Intent(c,MainActivity.class).setAction("com.quicknotes.app.WIDGET").putExtra("widgetList",intent.getStringExtra("widgetList")).putExtra("reminderId",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);c.startActivity(open);return;}JSONObject item=find(d,id);if(item==null||item.optBoolean("deleted")||!activeList(d,item.optString("list")))return;
  if("WIDGET_ROW".equals(action)){if(!ReminderWidget.canComplete(c,intent.getIntExtra(android.appwidget.AppWidgetManager.EXTRA_APPWIDGET_ID,-1))||item.optBoolean("done")||intent.getLongExtra("expectedDue",-1)!=item.optLong("due"))return;action="COMPLETE";}
  if("COMPLETE".equals(action)||"DISMISS".equals(action)){((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(id,id.hashCode());if("DISMISS".equals(action)&&AlarmService.current!=null)c.startService(AlarmService.command(c,"STOP",id));if("COMPLETE".equals(action)){if(!item.optBoolean("done"))Repeats.complete(d,id,System.currentTimeMillis());write(c,d);schedule(c,d);}c.sendBroadcast(new Intent(c.getPackageName()+".DATA_CHANGED").setPackage(c.getPackageName()));return;}
  long expected=intent.getLongExtra("expectedDue",-1),due=scheduledDue(item);if(expected!=due)return;if(intent.getBooleanExtra("early",false)){long earlyTime=earlyTime(item);if(!item.optBoolean("done")&&!item.optBoolean("urgent")&&hasEarly(item)&&earlyTime<=System.currentTimeMillis()&&System.currentTimeMillis()<due)notifyReminder(c,item,true);return;}long snooze=c.getSharedPreferences(PREFS,0).getLong("snooze:"+id,0);if(snooze>System.currentTimeMillis()+2000)return;if(due>System.currentTimeMillis()){schedule(c,d);return;}
  if(item.optBoolean("done")){if(item.optLong("nextDue")==0)return;reactivate(d,System.currentTimeMillis()+1000);write(c,d);item=find(d,id);if(item.optBoolean("done"))return;}
  SharedPreferences.Editor delivery=c.getSharedPreferences(PREFS,0).edit();if(item.optBoolean("urgent"))delivery.putLong("delivered:"+id,due);delivery.remove("snooze:"+id).remove("snooze-due:"+id).apply();
  if(item.optBoolean("urgent")&&item.optBoolean("timeEnabled",true)){Intent ring=new Intent(c,AlarmService.class).setAction("RING").putExtra("id",id).putExtra("expectedDue",item.optLong("due"));try{c.startForegroundService(ring);}catch(Exception e){notifyReminder(c,item);}}else notifyReminder(c,item);
 }}catch(Exception e){android.util.Log.e("QuickNotes","Reminder delivery failed",e);}finally{pending.finish();}},"quicknotes-delivery").start();}
 static PendingIntent action(Context c,String action,String id){return PendingIntent.getBroadcast(c,0,new Intent(c,Reminders.class).setAction(action).setData(android.net.Uri.parse("quicknotes://notification/"+action+"/"+id)).putExtra("id",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void notifyReminder(Context c,JSONObject item)throws Exception{notifyReminder(c,item,false);}
 static void notifyReminder(Context c,JSONObject item,boolean early)throws Exception{notifyReminder(c,item,early,true);}
 static void notifyReminder(Context c,JSONObject item,boolean early,boolean alert)throws Exception{
  NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(waitingForNotificationDue(item,System.currentTimeMillis())){String hiddenId=item.getString("id");nm.cancel(hiddenId,hiddenId.hashCode());return;}if(!alert&&item.optBoolean("flag")&&!item.optBoolean("urgent")&&c.getSharedPreferences(PREFS,0).getLong("delivered:"+item.getString("id"),-1)!=item.optLong("due"))return;if(!nm.areNotificationsEnabled())return;nm.createNotificationChannel(new NotificationChannel("reminders-v2","Reminder alerts",NotificationManager.IMPORTANCE_HIGH));NotificationChannel live=new NotificationChannel("flagged-live","Flagged reminders",NotificationManager.IMPORTANCE_LOW);live.setSound(null,null);nm.createNotificationChannel(live);String id=item.getString("id"),notes=item.optString("notes");boolean persistent=!early&&item.optBoolean("flag");
  PendingIntent open=PendingIntent.getActivity(c,id.hashCode(),new Intent(c,MainActivity.class).setAction("com.quicknotes.app.WIDGET").setData(android.net.Uri.parse("quicknotes://reminder/"+id)).putExtra("reminderId",id).putExtra("widgetList",item.optString("list")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Bundle extras=PhotoMetadata.extras(c,item);extras.putLong("quicknotes.due",item.optLong("due"));extras.putBoolean("quicknotes.early",early);extras.putBoolean("quicknotes.live",persistent&&!alert);
  Notification.Builder b=new Notification.Builder(c,persistent&&!alert?"flagged-live":"reminders-v2").addExtras(extras).setSmallIcon(R.drawable.ic_notification).setContentTitle((early?"Early reminder: ":"")+item.optString("title")).setContentText(notes).setStyle(new Notification.BigTextStyle().bigText(notes)).setContentIntent(open).setOnlyAlertOnce(!alert).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(!persistent).setOngoing(persistent).setWhen(item.optLong("due")).setShowWhen(persistent).addAction(new Notification.Action.Builder(null,"Dismiss",action(c,"DISMISS",id)).build()).addAction(new Notification.Action.Builder(null,"Mark As Completed",action(c,"COMPLETE",id)).build());
  if(!early&&item.optBoolean("urgent")){PendingIntent snooze=PendingIntent.getService(c,0,AlarmService.command(c,"SNOOZE",id).setData(android.net.Uri.parse("quicknotes://snooze/"+id)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);b.addAction(new Notification.Action.Builder(null,"Snooze 5 min",snooze).build());}if(persistent&&item.optLong("due")>0){b.setUsesChronometer(true);b.setChronometerCountDown(false);}nm.notify(id,id.hashCode(),b.build());if(alert&&!early&&item.optLong("due")>0&&item.optLong("due")<=System.currentTimeMillis()&&nm.getNotificationChannel("reminders-v2").getImportance()!=NotificationManager.IMPORTANCE_NONE)c.getSharedPreferences(PREFS,0).edit().putLong("delivered:"+id,item.optLong("due")).apply();
 }
}
